def tr(lang: str | None, key: str, **values: object) -> str:
    """Return a safe localized string; unsupported languages use English."""
    language = "fa" if lang == "fa" else "en"
    return TEXT[language].get(key, TEXT["en"].get(key, key)).format(**values)
